#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long power(long long base, int exp, long long mod) {
    long long res = 1LL;
    base %= mod;
    while (exp > 0) {
        if (exp & 1)
            res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

long long nCr(int n, int r, const std::vector<long long>& fact) {
    long long denom = (fact[r] * fact[n - r]) % MOD;
    long long denomInv = power(denom, MOD - 2, MOD);
    return (fact[n] * denomInv) % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N;
    long long K;
    cin >> N >> K;

    if (K >= N) {
        cout << 0 << "\n";
        return 0;
    }
    int C = N - K;

    std::vector<long long> factorials(200001);
    factorials[0] = 1;
    for (int i = 1; i <= 200000; i++) {
        factorials[i] = (factorials[i - 1] * i) % MOD;
    }

    long long answer = 0;
    int sign = 1;
    for (int i = C; i > 0; i--) {
        long long val = (nCr(C, i, factorials) * power(i, N, MOD)) % MOD;
        answer = (answer + sign * val + 2 * MOD) % MOD;
        sign *= -1;
    }

    long long mult = 2 * nCr(N, C, factorials);
    if (C == N)
        mult = 1LL;
    cout << (answer * mult) % MOD << "\n";

    return 0;
}

